import requests
import re
import json

try:
    response = requests.get('https://www.youtube.com/watch?v=aygSMgK3BEM')
    content = response.text

    # Extract ytInitialPlayerResponse
    player_response_match = re.search(r'var ytInitialPlayerResponse = ({.*?});', content, re.DOTALL)
    if player_response_match:
        player_response_json = player_response_match.group(1)

        # Try to parse JSON and look for transcript/caption info
        try:
            player_data = json.loads(player_response_json)

            # Look for captions/tracks
            if 'captions' in player_data:
                print('Found captions in player response')
                captions = player_data['captions']
                print('Captions structure:', type(captions))

            if 'contents' in player_data:
                contents = player_data['contents']
                if 'twoColumnWatchNextResults' in contents:
                    watch_next = contents['twoColumnWatchNextResults']
                    if 'results' in watch_next:
                        results = watch_next['results']
                        for result in results:
                            if 'results' in result:
                                for item in result['results']:
                                    if 'compactVideoRenderer' in item:
                                        video = item['compactVideoRenderer']
                                        print('Video title:', video.get('title', {}).get('simpleText', 'No title'))

        except json.JSONDecodeError as e:
            print('JSON decode error:', e)

except Exception as e:
    print('Error:', e)
