import requests
import re
import json

# Try to get more detailed information from the YouTube video
print('Attempting to get detailed information from the YouTube video...')

try:
    response = requests.get('https://www.youtube.com/watch?v=aygSMgK3BEM', headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'})
    content = response.text

    print('Looking for specific content about the scientists and their predictions...')

    # Try to extract the ytInitialPlayerResponse more carefully
    player_response_match = re.search(r'var ytInitialPlayerResponse = ({.*?});', content, re.DOTALL)
    if player_response_match:
        try:
            player_data = json.loads(player_response_match.group(1))

            # Look for video details and description
            if 'videoDetails' in player_data:
                video_details = player_data['videoDetails']
                title = video_details.get('title', 'No title')
                description = video_details.get('shortDescription', 'No description')

                print('Video Title:', title)
                print('Video Description:', description[:500])

                # Look for any content that might contain predictions
                if description:
                    # Look for prediction-related content in the description
                    prediction_terms = ['predict', 'prediction', 'by', 'in', 'year', 'think', 'machine', 'robot', 'develop', 'create', 'timeline', 'future']
                    found_predictions = []

                    for term in prediction_terms:
                        if term in description.lower():
                            found_predictions.append(term)

                    if found_predictions:
                        print('Found prediction-related terms in description:', found_predictions)

        except json.JSONDecodeError:
            print('Could not parse player response JSON')

    # Look for any content that mentions the scientists and predictions
    scientists = ['Jerome Wiesner', 'Oliver Selfridge', 'Claude Shannon']

    print('\\nLooking for scientist mentions and prediction context...')
    for scientist in scientists:
        if scientist in content:
            print(f'Found {scientist} in page content')

            # Get context around the scientist mention
            scientist_pos = content.find(scientist)
            if scientist_pos > 0:
                start = max(0, scientist_pos - 300)
                end = min(len(content), scientist_pos + len(scientist) + 300)
                context = content[start:end]

                # Look for prediction-related content in the context
                prediction_context = []
                for term in ['predict', 'prediction', 'by', 'in', 'year', 'think', 'machine', 'robot', 'develop', 'create', 'timeline', 'future']:
                    if term in context.lower():
                        prediction_context.append(term)

                if prediction_context:
                    print(f'  Prediction-related context: {prediction_context}')
                    print(f'  Context excerpt: {context[:200]}...')
        else:
            print(f'{scientist} not found in page content')

    # Look for any years that might be predictions
    years = re.findall(r'19[0-9]{2}', content)
    unique_years = list(set(years))
    if unique_years:
        print(f'\\nYears mentioned: {unique_years}')

except Exception as e:
    print('Error:', e)
""}

